<?php require __DIR__.'/includes/header.php'; $cid=currentCompanyId(); if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();if(!$cid)exit('Choose company');$data=['name_ar'=>$_POST['name_ar'],'name_en'=>$_POST['name_en'],'civil_id'=>$_POST['civil_id'],'phone'=>$_POST['phone'],'email'=>$_POST['email'],'nationality'=>$_POST['nationality'],'job_ar'=>$_POST['job_ar'],'job_en'=>$_POST['job_en'],'work_hours'=>$_POST['work_hours']];pending('worker_create',$cid,0,[], $data);audit('requested_create','worker');$msg=t('pending');} $sql='SELECT * FROM workers'.($cid?' WHERE company_id='.(int)$cid:'').' ORDER BY id DESC';$rows=db()->query($sql)->fetchAll(); ?>
