<dialog id="modal"><form method="post" class="modal-form"><h2>+ <?=t('workers')?></h2><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="form-grid"><label><?=t('name_ar')?><input name="name_ar" required></label><label><?=t('name_en')?><input name="name_en" required></label><label><?=t('civil_id')?><input name="civil_id" required></label><label><?=t('phone')?><input name="phone" required></label><label><?=t('email')?><input name="email"></label><label><?=t('nationality')?><input name="nationality"></label><label><?=t('job_ar')?><input name="job_ar"></label><label><?=t('job_en')?><input name="job_en"></label><label>Work Hours<input name="work_hours"></label></div><div class="actions"><button class="btn primary"><?=t('request_update')?></button><button type="button" class="btn" onclick="modal.close()"><?=t('close')?></button></div></form></dialog><?php require __DIR__.'/includes/footer.php'; ?>
